// dr-target: destructure-rest target. All exports are swept into the rest
// pattern by the importer, so every symbol here is retained conservatively.
// `ballast` is the passenger: nothing ever calls it; only the rest-pattern
// mechanism keeps it alive.
'use strict';

function a(seed) {
  const table = ['anchor', 'anvil', 'axle', 'auger', 'awl'];
  const text = String(seed);
  let acc = 13;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 29 + text.charCodeAt(i) * (i + 2)) % 9931;
  }
  const tag = table[acc % table.length];
  const rev = text.split('').reverse().join('');
  return 'destructure-rest:a:' + tag + ':' + acc + ':' + rev;
}
exports.a = a;

function b(seed) {
  const table = ['bolt', 'brace', 'bevel', 'burr', 'bit'];
  const text = String(seed);
  let acc = 23;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 43 + text.charCodeAt(i) * (i + 4)) % 9791;
  }
  const tag = table[acc % table.length];
  const upper = text.toUpperCase();
  return 'destructure-rest:b:' + tag + ':' + acc + ':' + upper;
}
exports.b = b;

function c(seed) {
  const table = ['clamp', 'chisel', 'caliper', 'cam', 'cog'];
  const text = String(seed);
  let acc = 31;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 47 + text.charCodeAt(i) * (i + 6)) % 9679;
  }
  const tag = table[acc % table.length];
  const lower = text.toLowerCase();
  return 'destructure-rest:c:' + tag + ':' + acc + ':' + lower;
}
exports.c = c;

function ballast(seed) {
  const table = ['keel', 'hull', 'mast', 'boom', 'bilge'];
  const text = String(seed);
  let acc = 53;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 53 + text.charCodeAt(i) * (i + 7)) % 9587;
  }
  const tag = table[acc % table.length];
  const doubled = text + text;
  return 'destructure-rest:ballast:' + tag + ':' + acc + ':' + doubled;
}
exports.ballast = ballast;
